// ffxiii2 - Final Fantasy XIII-2 (Europe, TU6), ReXGlue recompiled project.
// Stage 3 (first boot): the SDK's app as generated by `rexglue init`, plus only what the boot tests showed is needed,
// each with its evidence (docs/stage3-boot.md).
#pragma once

#include <filesystem>
#include <rex/graphics/graphics_system.h>
#include <rex/rex_app.h>
#include <rex/runtime.h>
#include <toml++/toml.hpp>

#include "ffxiii2_capture.h"
#include "ffxiii2_profile.h"

class Ffxiii2App : public rex::ReXApp {
 public:
  using rex::ReXApp::ReXApp;

  static std::unique_ptr<rex::ui::WindowedApp> Create(rex::ui::WindowedAppContext& ctx) {
    return std::unique_ptr<Ffxiii2App>(new Ffxiii2App(ctx, "ffxiii2", PPCImageConfig));
  }

  // Test captures of the presented frame (cvar ffxiii2_shots), for boot tests that keep the window minimized.
  void OnPostSetup() override {
    ffxiii2::profile::Start();  // cvar ffxiii2_profile_from_s (Windows sampling profiler, test runs)
    ffxiii2::capture::Start([this]() -> rex::ui::Presenter* {
      const auto* rt = runtime();
      const auto* graphics = rt ? rt->graphics_system() : nullptr;
      return graphics ? graphics->presenter() : nullptr;
    });
  }

  // ReXApp::SetupEnvironment resolves the game / update roots from the cvars BEFORE it loads ffxiii2.toml, so a
  // game_data_root written in the toml was ignored ("--game_data_root was not provided", first headless boot).
  // Take the two roots from the toml next to the exe when the command line did not give them.
  void OnConfigurePaths(rex::PathConfig& paths) override {
    if (!paths.game_data_root.empty() && !paths.update_data_root.empty()) return;
    std::error_code ec;
    if (!std::filesystem::exists(paths.config_path, ec)) return;
    try {
      const toml::table t = toml::parse_file(paths.config_path.string());
      if (paths.game_data_root.empty())
        if (auto v = t["game_data_root"].value<std::string>(); v && !v->empty()) paths.game_data_root = *v;
      if (paths.update_data_root.empty())
        if (auto v = t["update_data_root"].value<std::string>(); v && !v->empty()) paths.update_data_root = *v;
    } catch (const std::exception&) {
      // A broken toml is reported by the SDK's own LoadConfig right after this.
    }
  }
};
